    {
      "category": "learning_objective",
      "rationale": "Retain the mixed pairwise and pointwise objective and add 1e-4 regularization on the mean squared norm of nonpadding history, positive and negative embeddings. This controls magnitude growth when embedding normalization is removed across all four category models.",
      "edits": [
        {
          "find": "    loss = pairwise_loss + 0.2 * pointwise_loss\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)",
          "replace": "    loss = pairwise_loss + 0.2 * pointwise_loss\n    prediction_loss = (loss * mask).sum() / mask.sum().clamp(min=1.0)\n    squared_norm_sum = pos_scores.new_zeros(())\n    embedding_count = pos_scores.new_zeros(())\n    for item_ids in (seq, pos, neg):\n        nonpadding_ids = item_ids[item_ids.ne(0)]\n        embeddings = model.item_emb(nonpadding_ids)\n        squared_norm_sum = squared_norm_sum + embeddings.square().sum()\n        embedding_count = embedding_count + nonpadding_ids.numel()\n    norm_penalty = squared_norm_sum / embedding_count.clamp(min=1.0)\n    return prediction_loss + 1e-4 * norm_penalty"
        }
      ]
    },
    {
      "category": "embedding_representation",
      "rationale": "Remove unit normalization from the shared trainable item table, preserving its initialization, dimensions, tying and zero padding. The generated predictor imports this same model class, so training and inference remain consistent without checkpoint shape changes.",
