          "find": "        embeddings = super().forward(indices)\n        embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=-1, eps=1e-12)\n        return embeddings.masked_fill(indices.eq(0).unsqueeze(-1), 0.0)",
          "replace": "        embeddings = super().forward(indices)\n        return embeddings.masked_fill(indices.eq(0).unsqueeze(-1), 0.0)"
        }
